use transport_harness::{
    HarnessError,
    Output,
    cli::clap::{
        self,
        Parser,
    },
};

#[derive(Parser)]
#[command(name = "ticket-cli")]
struct TicketCommand {
    #[command(subcommand)]
    op: Op,
}

#[derive(clap::Subcommand)]
enum Op {
    /// Get a ticket by ID.
    Get {
        #[arg(long)]
        id: String,
        #[arg(long)]
        workspace: Option<String>,
    },
}

fn dispatch(command: TicketCommand) -> Result<Output, HarnessError> {
    match command.op {
        Op::Get { id, workspace } => {
            let workspace_path = workspace.unwrap_or_else(|| "default".to_string());
            let (path, _source) = ticket::workspace::resolve_workspace_by_name(&workspace_path);
            let store = ticket::storage::TicketStore::open(&path)
                .map_err(|e| HarnessError::domain(format!("failed to open store: {e}")))?;

            let ticket = store
                .get(&id)
                .map_err(|e| HarnessError::domain(format!("ticket not found: {e}")))?;

            Output::json(&ticket)
        }
    }
}

fn main() -> Result<(), HarnessError> {
    transport_harness::cli::run::<TicketCommand, _>(dispatch)
}

use serde::Deserialize;
use transport_harness::mcp::rmcp::{
    ErrorData as McpError,
    ServerHandler,
    handler::server::{
        tool::ToolRouter,
        wrapper::Parameters,
    },
    model::{
        CallToolResult,
        Content,
    },
    schemars::{
        self,
        JsonSchema,
    },
    tool,
    tool_handler,
    tool_router,
};

#[derive(Clone)]
struct TicketServer {
    tool_router: ToolRouter<Self>,
}

impl TicketServer {
    fn new() -> Self {
        Self {
            tool_router: Self::tool_router(),
        }
    }
}

#[derive(Debug, Deserialize, JsonSchema)]
struct GetArgs {
    /// Ticket ID to retrieve.
    id: String,
    /// Workspace name (default: "default").
    #[serde(default = "default_workspace")]
    workspace: String,
}

fn default_workspace() -> String {
    "default".to_string()
}

#[tool_router]
impl TicketServer {
    /// Get a ticket by ID.
    #[tool(description = "Get a ticket by ID")]
    async fn get(
        &self,
        Parameters(args): Parameters<GetArgs>,
    ) -> Result<CallToolResult, McpError> {
        let (path, _source) = ticket::workspace::resolve_workspace_by_name(&args.workspace);
        let store = ticket::storage::TicketStore::open(&path)
            .map_err(|e| McpError::invalid_params(format!("failed to open store: {e}"), None))?;

        let ticket = store
            .get(&args.id)
            .map_err(|e| McpError::invalid_params(format!("ticket not found: {e}"), None))?;

        let json = serde_json::to_string(&ticket)
            .map_err(|e| McpError::internal(format!("failed to serialize ticket: {e}"), None))?;

        Ok(CallToolResult::success(vec![Content::text(json)]))
    }
}

#[tool_handler]
impl ServerHandler for TicketServer {}

#[tokio::main]
async fn main() {
    let server = TicketServer::new();
    if let Err(err) = transport_harness::mcp::run(server).await {
        eprintln!("Fatal error: {err}");
        std::process::exit(1);
    }
}

use std::net::SocketAddr;
use transport_harness::http::{
    HttpError,
    Router,
    StatusCode,
    axum::{
        Json,
        extract::{Path, Query},
        response::{IntoResponse, Response},
        routing::get,
    },
};

#[derive(serde::Deserialize)]
struct GetQuery {
    workspace: Option<String>,
}

async fn get_ticket(
    Path(id): Path<String>,
    Query(query): Query<GetQuery>,
) -> Response {
    let workspace = query.workspace.unwrap_or_else(|| "default".to_string());
    let (path, _source) = ticket::workspace::resolve_workspace_by_name(&workspace);

    let store = match ticket::storage::TicketStore::open(&path) {
        Ok(store) => store,
        Err(e) => {
            return HttpError::new(
                StatusCode::INTERNAL_SERVER_ERROR,
                "store_error",
                format!("failed to open store: {e}"),
            )
            .into_response()
        }
    };

    match store.get(&id) {
        Ok(ticket) => Json(ticket).into_response(),
        Err(e) => HttpError::new(
            StatusCode::NOT_FOUND,
            "not_found",
            format!("ticket not found: {e}"),
        )
        .into_response(),
    }
}

fn router() -> Router {
    Router::new().route("/ticket/{id}", get(get_ticket))
}

#[tokio::main]
async fn main() {
    let addr = SocketAddr::from(([127, 0, 0, 1], 3010));
    println!("ticket-http listening on {addr}");

    if let Err(err) = transport_harness::http::run(addr, router()).await {
        eprintln!("Fatal error: {err}");
        std::process::exit(1);
    }
}

